{
     "title": "CSCI-455: Principles of Cybersecurity - Foundations Lesson Blueprint",
     "learningObjectives": [
       "Define the core crosscutting concepts of confidentiality, integrity, and availability as foundational security properties.",
       "Explain how the Secure Software Development Framework (SSDF) practice groups structure secure software development processes.",
       "Apply adversarial thinking and systems thinking to analyze real-world security risks and policy mechanisms."
     ],
     "beats": [
       {
         "title": "Lesson Title: Foundations of Cybersecurity Principles",
         "claim": "Confidentiality, integrity, and availability form the core triad of security properties that protect information and systems.",
         "example": "A hospital's electronic health records must remain confidential from unauthorized users, maintain integrity against tampering, and remain available during peak patient intake hours.",
         "visualDirection": "Display a simple Venn diagram showing the overlapping circles of confidentiality, integrity, and availability, with a central 'Secure System' label.",
         "sourceIds": ["nist-cryptographic-standards", "rit-csci-455"]
       },
       {
         "title": "Lesson Title: Cryptographic Standards and Confidentiality",
         "claim": "Cryptographic standards define approved algorithms and parameters that enable encryption to support confidentiality when keys and modes are used correctly.",
         "example": "AES-256 encryption with proper key management ensures patient data remains unreadable to unauthorized personnel, satisfying confidentiality requirements.",
         "visualDirection": "Show a flowchart: Plaintext -> Encryption Algorithm (AES-256) -> Ciphertext, with a lock icon labeled 'Confidentiality'.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Lesson Title: Integrity and Authentication Mechanisms",
         "claim": "Message authentication and digital signatures address integrity and authenticity in different ways, ensuring data has not been altered.",
         "example": "A digital signature on a software update verifies the developer's identity and confirms the code has not been modified during transmission.",
         "visualDirection": "Display a side-by-side comparison: Hash-based message authentication (integrity check) vs. Digital signature (integrity + authenticity).",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {

       "title": "Lesson Title: Secure Software Development Framework (SSDF)",
       "claim": "The Secure Software Development Framework groups practices into four practice groups: Prepare the Organization, Protect the Software, Produce Well-Secured Software, and Respond to ",
       "example": "A development team uses the 'Prepare the Organization' group to establish secure coding standards and training before writing any code.",
       "visualDirection": "Create a four-step circular diagram labeled with the four SSDF practice groups, connected by arrows indicating iterative flow.",
       "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Lesson Title: Security Requirements and Verification",
         "claim": "Security requirements should be tracked throughout development, and verification provides evidence that selected practices and controls were performed.",
         "example": "A compliance officer reviews a checklist to verify that all encryption standards and access controls were implemented before software release.",
         "visualDirection": "Show a checklist graphic with checkboxes next to security requirements, highlighting 'Verification' as the final step.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Lesson Title: Vulnerability Management and Response",
         "claim": "Respond to Vulnerabilities identifies, analyzes, remediates, and learns from discovered weaknesses, closing the security lifecycle.",
         "example": "After a penetration test reveals an unpatched database vulnerability, the team patches the code, updates documentation, and trains developers on secure input validation.",
         "visualDirection": "Display a feedback loop diagram: Vulnerability Discovery -> Analysis -> Remediation -> Learning/Improvement.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Lesson Title: Adversarial Thinking and Threat Modeling",
         "claim": "Security reasoning identifies assets, trust boundaries, threats, controls, evidence, residual risk, and responsibilities to guide defensive design.",
         "example": "An analyst maps a web application's trust boundary, identifies a potential SQL injection threat, and assigns a control to validate all user inputs.",
         "visualDirection": "Show a trust boundary diagram with internal assets, external threats, and a labeled 'Control' zone between them.",
         "sourceIds": ["nist-ssdf", "rit-csci-455"]
       },
       {
         "title": "Lesson Title: Systems Thinking and Crosscutting Concepts",
         "claim": "Systems thinking evaluates how confidentiality, integrity, availability, risk, and policy mechanisms interact across data, software, and human components.",
         "example": "A policy requiring multi-factor authentication reduces risk by addressing both human behavior and system access points simultaneously.",
         "visualDirection": "Create a layered system model showing data, software, human, and policy layers, with arrows indicating cross-cutting security concepts.",
         "sourceIds": ["rit-csci-455"]
       },
       {
         "title": "Lesson Title: Privacy, Ethics, and Legal Compliance",
         "claim": "Privacy, legal, and ethical aspects must be integrated into security policies to ensure responsible and compliant system design.",
         "example": "A healthcare app implements data minimization and consent mechanisms to comply with privacy regulations while maintaining security.",
         "visualDirection": "Display a balance scale graphic with 'Security' on one side and 'Privacy/Ethics/Legal' on the other, labeled 'Balanced Design'.",
         "sourceIds": ["rit-csci-455"]
       },
       {
         "title": "Lesson Title: Practical Analysis Checklist",
         "claim": "Students must apply foundational concepts to evaluate real-world scenarios using a structured checklist for confidentiality, integrity, availability, and risk.",
         "example": "An auditor reviews a cloud migration plan against the checklist to verify encryption, access controls, backup availability, and risk mitigation steps.",
         "visualDirection": "Show a printable checklist template with columns for 'Component', 'Confidentiality', 'Integrity', 'Availability', 'Risk Level', and 'Mitigation'.",
         "sourceIds": ["nist-cryptographic-standards", "nist-ssdf"]
       }
     ]
   }
